/* Personal digest: one isolated reader, authenticated data from the existing app. */
let pdEdition=null,pdFrame=null;
async function openPersonalDigest(start,end){
 pdFeatureOpened('digest');
  dgsLoading('Собираем твою выжимку…');dgsPdfBtn(false);dgsShareBtnShow(false);dgsMode='personal';
  try{
    const q=new URLSearchParams();if(start)q.set('start',start);if(end)q.set('end',end);
    const d=await apiRequest(API_URL+'/digest/personal?'+q);pdEdition=d;
    const host=document.getElementById('dgs-pages');host.innerHTML='';
    pdFrame=document.createElement('iframe');pdFrame.title='Твоя персональная выжимка';pdFrame.sandbox='allow-scripts allow-same-origin';pdFrame.allow='accelerometer; gyroscope';
    pdFrame.style='width:100%;height:calc(100dvh - 28px);border:0;display:block';host.appendChild(pdFrame);
    pdFrame.srcdoc=pdDocument(d);document.getElementById('dgs-count').textContent='';
  }catch(e){dgsEmpty('Не получилось открыть выжимку. Проверь вход в клуб и попробуй ещё раз.');}
}
function pdDocument(d){
 const E=escapeHtml,A='<svg class="nouveau-arrow" viewBox="0 0 56 32" fill="none" aria-hidden="true"><path d="M3 23C12 23 15 9 25 10C31 10 30 21 23 21C17 21 19 16 25 16H50M41 8C43 13 47 16 51 16C47 17 43 20 41 25" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>',button=(text,action,i)=>'<a href="#" data-action="'+action+'" data-i="'+i+'" class="action">'+E(text)+A+'</a>';
 const month=s=>dgsMonth(s),range=month(d.start)+(d.start!==d.end?' — '+month(d.end):'');
 const sheet=(body,kind,n)=>'<section id="pd-page-'+n+'" class="sheet '+kind+'"><header class="mast"><span>Боженька продаж</span><span>'+E(range)+'</span></header><div class="pagebody"><div class="rule"></div>'+body+'</div><footer class="foot">'+n+' / '+(d.pages.length+1)+'</footer></section>';
 const toc=[['idea','Главные мысли этого месяца'],['card','Твои коллекционные карты'],['news','Новые фичи клуба']].map(([kind,title])=>({title,index:d.pages.findIndex(p=>p.kind===kind)})).filter(x=>x.index>=0).map((x,i)=>'<li><a href="#pd-page-'+(x.index+2)+'"><span class="toc-number">'+String(i+1).padStart(2,'0')+'</span><span class="toc-label">'+E(x.title)+'</span>'+A+'</a></li>').join('');
 const intro='<h1>Что было в клубе за '+(d.start===d.end?'этот месяц':'эти месяцы')+'</h1><p class="subtitle">Твой шот эспрессо, чтобы быстро нагнать материал (и радоваться)</p><p class="instruction">Дайджест интерактивный, нажимай, трогай.</p><h2>Что внутри</h2><ul class="nouveau-toc">'+toc+'</ul>'+(d.idea_count?'':'<p>Мысли за этот период ещё проходят редактуру. Можно выбрать другой месяц.</p>')+'<h2>За это время мы обсудили</h2>'+d.lectures.map((l,i)=>button(l.title,'topic',i)).join('');
 const nowParts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit'}).formatToParts(new Date());
 const current=nowParts.find(p=>p.type==='year').value+'-'+nowParts.find(p=>p.type==='month').value;
 const months=[];for(let y=2026,m=8;;){const key=y+'-'+String(m).padStart(2,'0');if(key>=current)break;months.push(key);if(++m===13){m=1;y++}}
 const periodUI='<div class="pd-toolbar"><span>'+E(range)+'</span><button type="button" id="period-open">Изменить период</button></div><div class="pd-toolbar pd-export"><button type="button" data-action="pdf" data-i="0">Скачать PDF</button></div><dialog id="period-dialog" aria-labelledby="period-title"><div class="pd-dialog-head"><h2 id="period-title">За какой период?</h2><button type="button" id="period-close" aria-label="Закрыть">×</button></div><p>Выбери месяц. Для нескольких — нажми первый и последний.</p><div class="pd-months">'+months.map(m=>'<button type="button" data-month="'+m+'" aria-pressed="'+(m>=d.start&&m<=d.end)+'">'+E(month(m))+'</button>').join('')+'</div><p id="period-choice" aria-live="polite">'+E(range)+'</p><button type="button" id="period-apply">Читать выжимку</button></dialog>';
 const configs=[];
 const pages=d.pages.map((p,i)=>{
  if(p.kind==='idea')return sheet('<p class="eyebrow">Главные мысли этого месяца</p><article class="quote"><h3>'+E(p.title)+'</h3><blockquote>'+E(p.text)+'</blockquote><p class="source">'+E(p.lecture)+'<br>'+E(p.time)+'</p><div class="actions">'+(p.has_audio?button('Слушать с '+p.time,'audio',i):'')+button('Открыть занятие','lecture',i)+'</div><div class="audio-slot" id="audio-'+i+'"></div></article>','quote-page',i+2);
  if(p.kind==='card'){const c=p.card;configs.push(c.holo);return sheet('<p class="eyebrow">Твои коллекционные карты</p><h2>'+E(c.god||c.title)+'</h2><div class="card-stand">'+(c.sigil_url?'<img class="card-sigil" src="'+E(c.sigil_url)+'" alt="">':'')+'<div class="card-scene"><div class="card-art"><img src="'+E(c.art_url||c.image_url)+'" alt="'+E(c.title||c.god)+'"></div>'+(p.frame_url?'<img class="card-frame" src="'+E(p.frame_url)+'" alt="">':'')+'</div></div><p class="bonus">'+E(c.effect_type==='points'?'+'+c.effect_points+' баллов':c.title||'Твоя награда')+'</p><p class="bonus-caption">'+E(p.effect_applied?'Бонус этой карты уже применён':'Посмотри награду в коллекции')+'</p>'+button('Посмотреть мои карты','cards',i)+'<button type="button" class="action pd-gyro">Включить наклон</button><p class="gyro-status" role="status"></p>','card-page',i+2);}
  if(p.kind==='news')return sheet('<p class="eyebrow">Новое в клубе</p><h2>'+E(p.title)+'</h2><p class="news-copy">'+E(p.text)+'</p>'+p.links.filter(l=>/^https:\/\//.test(l.url||'')).map((l,j)=>button(l.label||'Подробнее','news-'+j,i)).join(''),'news-page',i+2);
  return sheet('<p class="eyebrow">Возможно, ты ещё не пробовал</p><h2>'+E(p.title)+'</h2><p class="feature-intro">Познакомься с возможностями клуба.</p>'+button('Посмотреть, как это работает','feature',i),'feature-page',i+2);
 }).join('');
 const js=`(${String(pdPeriodControls)})(${JSON.stringify({start:d.start,end:d.end})});document.addEventListener('click',e=>{const toc=e.target.closest('a[href^="#pd-page-"]');if(toc){e.preventDefault();document.getElementById(toc.getAttribute('href').slice(1))?.scrollIntoView({behavior:'smooth'});return}const a=e.target.closest('[data-action]');if(!a)return;e.preventDefault();parent.postMessage({personalDigest:true,action:a.dataset.action,index:Number(a.dataset.i)},'*')});window.addEventListener('message',e=>{if(e.source!==parent||!e.data.audio)return;const slot=document.getElementById('audio-'+e.data.index);if(!slot)return;document.querySelectorAll('audio').forEach(a=>a.pause());const a=document.createElement('audio');a.controls=true;a.src=e.data.audio;slot.replaceChildren(a);a.onloadedmetadata=()=>{a.currentTime=e.data.seconds;a.play().catch(()=>{})}});`;
 return '<!doctype html><html lang="ru"><meta name="viewport" content="width=device-width,initial-scale=1"><style>'+PD_CSS+PD_PERIOD_CSS+'a,a:hover,a:active{background:transparent!important}button{cursor:pointer}</style><body>'+periodUI+'<main id="digest-scroll">'+sheet(intro,'cover',1)+pages+'</main><script>'+PD_HOLO+';'+js+';('+String(pdHoloMount)+')('+JSON.stringify(configs).replace(/</g,'\\u003c')+');<\/script></body></html>';
}
window.addEventListener('message',async e=>{
 if(!pdFrame||e.source!==pdFrame.contentWindow||!e.data?.personalDigest||dgsMode!=='personal')return;
 const x=e.data,p=pdEdition.pages[x.index];
 if(['topic','lecture','cards','feature'].includes(x.action))window.pdReturnToWinback=false;
 if(x.action==='pdf'){await pdDownload();return}
 if(x.action==='period'){await openPersonalDigest(x.start,x.end);return}
 if(x.action==='topic'){const l=pdEdition.lectures[x.index];if(l)dgsOpenLecture(l.slug,'');return}
 if(!p)return;
 if(x.action==='lecture'&&p.kind==='idea'){dgsOpenLecture(p.slug,'');return}
 if(x.action==='audio'&&p.kind==='idea'){
  try{const d=await apiRequest(API_URL+'/lectures/'+encodeURIComponent(p.slug)+'/audio'+dgsWho());if(!d.url)return;const seconds=p.time.split(':').reduce((a,n)=>a*60+Number(n),0);if(d.full===false&&seconds>=(d.preview_minutes||0)*60){openPaywall();return}pdFrame.contentWindow.postMessage({audio:d.url,index:x.index,seconds},'*')}catch(e){showToast('Не удалось открыть аудио')};return;
 }
 if(x.action==='cards'&&p.kind==='card'){closeDigest();switchView('cards');return}
 if(x.action==='feature'&&p.kind==='feature'){closeDigest();await loadStories();storyOpen(p.id);return}
 if(x.action.startsWith('news-')&&p.kind==='news'){const l=p.links[Number(x.action.slice(5))];if(l&&/^https:\/\//.test(l.url))window.open(l.url,'_blank','noopener')}
});

function pdHoloMount(configs){try{if(parent.Telegram)window.Telegram=parent.Telegram}catch(e){}if(matchMedia('(prefers-reduced-motion: reduce)').matches){document.querySelectorAll('.pd-gyro').forEach(b=>{b.disabled=true;b.textContent='Наклон отключён настройкой движения'});return}const mounts=new Map();const cards=[...document.querySelectorAll('.card-page')];const io=new IntersectionObserver(entries=>entries.forEach(e=>{const el=e.target,cfg=configs[cards.indexOf(el)];if(e.isIntersecting&&!mounts.has(el)&&cfg?.on){const scene=el.querySelector('.card-scene');mounts.set(el,HoloFX.mount(el.querySelector('.card-art'),cfg,{input:scene,tiltEl:scene,gyro:false,touch:false,z:2}))}else if(!e.isIntersecting&&mounts.has(el)){mounts.get(el).destroy();mounts.delete(el)}}));cards.forEach(el=>io.observe(el));document.addEventListener('click',e=>{const b=e.target.closest('.pd-gyro');if(!b)return;const section=b.closest('.card-page'),status=section.querySelector('.gyro-status'),fx=mounts.get(section);if(!fx){status.textContent='Наклон недоступен при отключённых эффектах.';return}fx.startGyro(true,(ok)=>{status.textContent=ok?'Наклоняй телефон — карта движется вместе с ним.':'Датчик недоступен или разрешение не выдано.'})});}

function destroyPersonalDigest(){if(pdFrame){pdFrame.remove();pdFrame=null;}pdEdition=null;}

const PD_PERIOD_CSS=`.pd-toolbar{max-width:430px;margin:auto;padding:48px 22px 8px;box-sizing:border-box;display:flex;align-items:center;justify-content:space-between;gap:12px;color:#d9cdbb;font:13px/1.4 -apple-system,sans-serif}.pd-export{padding:0 22px 4px;justify-content:flex-end}.pd-gyro{cursor:pointer}.pd-toolbar button{appearance:none;font:inherit;color:#dfb991;border:0;border-bottom:1px solid #9a7d4d;background:none;padding:7px 0;cursor:pointer;min-height:44px}#period-dialog{box-sizing:border-box;width:calc(100% - 28px);max-width:400px;max-height:85dvh;overflow:auto;border:1px solid #9a7d4d66;border-radius:22px;padding:24px;background:#f3eadb;color:#211c18;box-shadow:0 22px 70px #0006}#period-dialog::backdrop{background:#171713aa;backdrop-filter:blur(5px)}.pd-dialog-head{display:flex;align-items:start;gap:12px;justify-content:space-between}.pd-dialog-head h2{font:30px/1.15 Georgia,serif;margin:4px 0 18px}.pd-dialog-head button{appearance:none;border:1px solid #9a7d4d66;border-radius:50%;background:transparent;color:#5d5348;width:36px;height:36px;font:24px/1 sans-serif;flex-shrink:0}#period-dialog p{font:15px/1.5 -apple-system,sans-serif;color:#6e6254}.pd-months{display:grid;gap:10px;margin:22px 0;max-height:35dvh;overflow:auto}.pd-months button{appearance:none;text-align:left;border:1px solid #9a7d4d66;border-radius:12px;padding:14px 16px;background:transparent;color:#211c18;font:16px/1.3 -apple-system,sans-serif;min-height:48px}.pd-months button[aria-pressed=true]{border-color:#914b3d;background:#914b3d0c;color:#914b3d;box-shadow:inset 3px 0 #914b3d}#period-apply{appearance:none;border:0;border-radius:12px;min-height:48px;width:100%;padding:14px;background:#30372c;color:#f3eadb;font:16px/1.3 -apple-system,sans-serif}#period-dialog button:focus-visible{outline:2px solid #914b3d;outline-offset:3px}`;
function pdPeriodControls(initial){
 const dialog=document.getElementById('period-dialog'),buttons=[...dialog.querySelectorAll('[data-month]')];let start=initial.start,end=initial.end,anchor=null;
 const paint=()=>{buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.month>=start&&b.dataset.month<=end)));const label=k=>buttons.find(b=>b.dataset.month===k)?.textContent||'';document.getElementById('period-choice').textContent=label(start)+(start===end?'':' — '+label(end))};
 document.getElementById('period-open').onclick=()=>{anchor=null;dialog.showModal()};document.getElementById('period-close').onclick=()=>dialog.close();
 buttons.forEach(b=>b.onclick=()=>{const key=b.dataset.month;if(!anchor){start=end=anchor=key}else{start=key<anchor?key:anchor;end=key>anchor?key:anchor;anchor=null}paint()});
 document.getElementById('period-apply').onclick=()=>{dialog.close();parent.postMessage({personalDigest:true,action:'period',start,end},'*')};
}

const pdFeatureSeen=new Set();
function pdFeatureOpened(name){const feature=({ai:'search',search:'search',plan:'plan',games:'games',cards:'cards',library:'library',magazine:'magazine',live:'live',invite:'invite',notifications:'notifications',digest:'digest',install:'install',audio:'audio',insights:'insights',card_share:'card_share'})[name];if(!feature||pdFeatureSeen.has(feature))return;pdFeatureSeen.add(feature);if(feature!=='install'&&(matchMedia('(display-mode: standalone)').matches||navigator.standalone))pdFeatureOpened('install');apiRequest(API_URL+'/digest/personal/feature-open',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({feature})}).catch(()=>pdFeatureSeen.delete(feature));}

let pdPdfBusy=false;
async function pdDownload(){
 if(!pdEdition||pdPdfBusy)return;pdPdfBusy=true;const edition={start:pdEdition.start,end:pdEdition.end};showToast('Готовим PDF…');
 try{const q=new URLSearchParams(edition);const r=await fetchWithTimeout(API_URL+'/digest/personal/pdf?'+q,{},120000);if(!r.ok||!r.response.ok)throw Error();const blob=await r.response.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Твоя выжимка '+edition.start+' — '+edition.end+'.pdf';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);showToast('PDF готов')}catch(e){showToast('Не удалось подготовить PDF. Попробуй ещё раз.')}finally{pdPdfBusy=false}
}
